import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Automatic checker for Practice.java. Do NOT edit this file.
 *
 *   javac Practice.java Checker.java SortedScores.java
 *   java Checker
 */
public class Checker {

    // ---------- tiny test framework ----------

    interface Body { void run() throws Throwable; }

    static class Fail extends RuntimeException {
        Fail(String message) { super(message); }
    }

    static class Check {
        final String name;
        final Body body;
        Check(String name, Body body) { this.name = name; this.body = body; }
    }

    static class Problem {
        final String title;
        final List<Check> checks = new ArrayList<>();
        Problem(String title) { this.title = title; }
        Problem add(String name, Body body) {
            checks.add(new Check(name, body));
            return this;
        }
    }

    static String source = "";

    static String show(Object o) {
        if (o instanceof int[]) return Arrays.toString((int[]) o);
        if (o instanceof Object[]) return Arrays.deepToString((Object[]) o);
        if (o instanceof String) return "\"" + o + "\"";
        return String.valueOf(o);
    }

    static void eq(Object expected, Object actual) {
        eq(expected, actual, null);
    }

    static void eq(Object expected, Object actual, String hint) {
        if (!Objects.deepEquals(expected, actual)) {
            String msg = "expected " + show(expected) + " but got " + show(actual);
            if (hint != null) msg += "  (" + hint + ")";
            throw new Fail(msg);
        }
    }

    static void isTrue(boolean condition, String message) {
        if (!condition) throw new Fail(message);
    }

    // ---------- looking at the student's source code ----------

    static String stripComments(String code) {
        code = code.replaceAll("(?s)/\\*.*?\\*/", " ");
        code = code.replaceAll("//[^\\n]*", " ");
        return code.replaceAll("\"(\\\\.|[^\"\\\\])*\"", "\"\"");
    }

    /** The code inside a method's { }, without comments or string text. */
    static String bodyOf(String method) {
        String code = stripComments(source);
        Matcher m = Pattern.compile("static\\s+[^;{(]*?\\b" + method + "\\s*\\(").matcher(code);
        if (!m.find()) throw new Fail("Could not find the method " + method + "()");
        int open = code.indexOf('{', m.end());
        int depth = 0;
        for (int i = open; i < code.length(); i++) {
            if (code.charAt(i) == '{') depth++;
            if (code.charAt(i) == '}') {
                depth--;
                if (depth == 0) return code.substring(open + 1, i);
            }
        }
        throw new Fail("Could not read the method " + method + "()");
    }

    static void notAllowed(String method, String... banned) {
        String body = bodyOf(method);
        for (String word : banned) {
            if (body.contains(word)) {
                throw new Fail("Not allowed: " + word);
            }
        }
    }

    static void mustCallItself(String method) {
        if (!bodyOf(method).contains(method + "(")) {
            throw new Fail("Your method must call itself (recursion)");
        }
    }

    static void noLoops(String method) {
        Matcher m = Pattern.compile("\\b(for|while|do)\\b").matcher(bodyOf(method));
        if (m.find()) throw new Fail("No loops allowed. Use recursion instead.");
    }

    // ---------- the problems ----------

    static int[] arr(int... values) { return values; }

    static List<Problem> buildProblems() {
        List<Problem> list = new ArrayList<>();

        list.add(new Problem("1.  Playtime clock")
            .add("zero", () -> eq("00:00:00", Practice.formatPlaytime(0)))
            .add("seconds only", () -> eq("00:00:59", Practice.formatPlaytime(59)))
            .add("minutes", () -> eq("00:02:05", Practice.formatPlaytime(125)))
            .add("basic", () -> eq("01:02:05", Practice.formatPlaytime(3725)))
            .add("exactly one hour", () -> eq("01:00:00", Practice.formatPlaytime(3600)))
            .add("almost a day", () -> eq("23:59:59", Practice.formatPlaytime(86399))));

        list.add(new Problem("2.  Take damage")
            .add("basic", () -> eq(80, Practice.applyDamage(100, 30, 10)))
            .add("no armor", () -> eq(70, Practice.applyDamage(100, 30, 0)))
            .add("armor stronger than hit",
                () -> eq(100, Practice.applyDamage(100, 5, 10), "armor can't heal you"))
            .add("armor equals hit", () -> eq(50, Practice.applyDamage(50, 10, 10)))
            .add("health never below zero",
                () -> eq(0, Practice.applyDamage(20, 50, 0), "health can't go negative"))
            .add("exactly lethal", () -> eq(0, Practice.applyDamage(30, 40, 10))));

        list.add(new Problem("3.  Rewind")
            .add("basic", () -> eq(arr(3, 2, 1), Practice.reverseArray(arr(1, 2, 3))))
            .add("even length", () -> eq(arr(4, 3, 2, 1), Practice.reverseArray(arr(1, 2, 3, 4))))
            .add("edges", () -> {
                eq(arr(), Practice.reverseArray(arr()));
                eq(arr(7), Practice.reverseArray(arr(7)));
            })
            .add("does not change original", () -> {
                int[] original = {1, 2, 3, 4};
                Practice.reverseArray(original);
                eq(arr(1, 2, 3, 4), original, "build a NEW array");
            })
            .add("returns a new array", () -> {
                int[] original = {1, 2};
                isTrue(Practice.reverseArray(original) != original, "Return a NEW array");
            })
            .add("no shortcuts", () -> notAllowed("reverseArray", "Collections", "reverse")));

        list.add(new Problem("4.  Strongest enemy")
            .add("basic", () -> eq(1, Practice.strongestEnemyIndex(arr(40, 90, 55))))
            .add("first position", () -> eq(0, Practice.strongestEnemyIndex(arr(99, 5, 7))))
            .add("last position", () -> eq(2, Practice.strongestEnemyIndex(arr(1, 2, 3))))
            .add("tie returns first",
                () -> eq(1, Practice.strongestEnemyIndex(arr(40, 90, 55, 90))))
            .add("negative numbers",
                () -> eq(1, Practice.strongestEnemyIndex(arr(-5, -2, -9))))
            .add("single and empty", () -> {
                eq(0, Practice.strongestEnemyIndex(arr(10)));
                eq(-1, Practice.strongestEnemyIndex(arr()));
            })
            .add("no shortcuts", () -> notAllowed("strongestEnemyIndex", "sort", "stream")));

        list.add(new Problem("5.  Tidy the loot")
            .add("basic", () -> eq(list("sword", "potion", "key"),
                Practice.uniqueItems(list("sword", "potion", "sword", "key", "potion"))))
            .add("keeps order", () -> eq(list("z", "a", "m"),
                Practice.uniqueItems(list("z", "a", "z", "m")), "keep the original order"))
            .add("no duplicates and empty", () -> {
                eq(list("a", "b"), Practice.uniqueItems(list("a", "b")));
                eq(list(), Practice.uniqueItems(list()));
            })
            .add("all same", () -> eq(list("x"), Practice.uniqueItems(list("x", "x", "x"))))
            .add("case sensitive", () -> eq(list("Gem", "gem"),
                Practice.uniqueItems(list("Gem", "gem", "Gem"))))
            .add("does not change original", () -> {
                ArrayList<String> original = list("a", "a", "b");
                Practice.uniqueItems(original);
                eq(list("a", "a", "b"), original, "don't modify the list that was passed in");
            }));

        list.add(new Problem("6.  Same inventory?")
            .add("true", () -> eq(true, Practice.sameInventory(
                new String[]{"Sword", "Potion", "Key"}, new String[]{"key", "SWORD", "potion"})))
            .add("false", () -> eq(false, Practice.sameInventory(
                new String[]{"Sword", "Potion"}, new String[]{"Sword", "Shield"})))
            .add("different counts", () -> eq(false, Practice.sameInventory(
                new String[]{"a", "a", "b"}, new String[]{"a", "b", "b"}),
                "same items but different counts is NOT the same"))
            .add("different lengths", () -> eq(false, Practice.sameInventory(
                new String[]{"a"}, new String[]{"a", "b"})))
            .add("empty", () -> eq(true, Practice.sameInventory(new String[]{}, new String[]{})))
            .add("does not change inputs", () -> {
                String[] a = {"B", "A"};
                String[] b = {"a", "b"};
                Practice.sameInventory(a, b);
                eq(new String[]{"B", "A"}, a, "don't modify the arrays that were passed in");
                eq(new String[]{"a", "b"}, b, "don't modify the arrays that were passed in");
            }));

        list.add(new Problem("7.  Find a score")
            .add("found", () -> eq(3, Practice.findScore(
                new SortedScores(arr(0, 12, 24, 48, 96)), 48)))
            .add("first and last", () -> {
                SortedScores s = new SortedScores(arr(0, 12, 24, 48, 96));
                eq(0, Practice.findScore(s, 0));
                eq(4, Practice.findScore(s, 96));
            })
            .add("not found", () -> {
                SortedScores s = new SortedScores(arr(0, 12, 24, 48, 96));
                eq(-1, Practice.findScore(s, 50));
                eq(-1, Practice.findScore(s, -5));
                eq(-1, Practice.findScore(s, 1000));
            })
            .add("empty and single", () -> {
                eq(-1, Practice.findScore(new SortedScores(arr()), 5));
                eq(0, Practice.findScore(new SortedScores(arr(7)), 7));
                eq(-1, Practice.findScore(new SortedScores(arr(7)), 8));
            })
            .add("every item is found", () -> {
                int[] data = new int[34];
                for (int i = 0; i < data.length; i++) data[i] = i * 3;
                SortedScores s = new SortedScores(data);
                for (int i = 0; i < data.length; i++) eq(i, Practice.findScore(s, data[i]));
            })
            .add("is really binary search", () -> {
                SortedScores s = SortedScores.evens(1_000_000);
                eq(617_284, Practice.findScore(s, 1_234_568));
                isTrue(s.getLooks() < 100, "You looked at " + s.getLooks()
                    + " items out of 1,000,000. Binary search needs only about 20.");
            })
            .add("missing in a huge list is fast too", () -> {
                SortedScores s = SortedScores.evens(1_000_000);
                eq(-1, Practice.findScore(s, 7));
                isTrue(s.getLooks() < 100, "You looked at " + s.getLooks()
                    + " items. Binary search needs only about 20.");
            })
            .add("no shortcuts", () -> notAllowed("findScore", "binarySearch", "indexOf")));

        list.add(new Problem("8.  Count the drops")
            .add("basic", () -> eq(map("gold", 2, "gem", 1),
                Practice.countDrops(new String[]{"gold", "gem", "gold"})))
            .add("empty", () -> eq(map(), Practice.countDrops(new String[]{})))
            .add("all same", () -> eq(map("gold", 4),
                Practice.countDrops(new String[]{"gold", "gold", "gold", "gold"})))
            .add("many", () -> eq(map("gold", 3, "gem", 1, "potion", 2),
                Practice.countDrops(new String[]{"gold", "potion", "gold", "gem", "gold", "potion"}))));

        list.add(new Problem("9.  Poison")
            .add("zero", () -> eq(0, Practice.totalPoisonDamage(0)))
            .add("one", () -> eq(1, Practice.totalPoisonDamage(1)))
            .add("three", () -> eq(6, Practice.totalPoisonDamage(3)))
            .add("five", () -> eq(15, Practice.totalPoisonDamage(5)))
            .add("bigger", () -> eq(5050, Practice.totalPoisonDamage(100)))
            .add("must be recursive", () -> mustCallItself("totalPoisonDamage"))
            .add("no loops", () -> noLoops("totalPoisonDamage")));

        list.add(new Problem("10. CHALLENGE: chests")
            .add("flat", () -> eq(3, Practice.countItems(new Object[]{"sword", "gem", "key"})))
            .add("empty", () -> eq(0, Practice.countItems(new Object[]{})))
            .add("one chest inside", () -> eq(3, Practice.countItems(
                new Object[]{"sword", new Object[]{"gem", "key"}})))
            .add("nested", () -> eq(5, Practice.countItems(
                new Object[]{"sword", new Object[]{"potion", "key", new Object[]{"gem"}}, "shield"})))
            .add("deep", () -> eq(1, Practice.countItems(
                new Object[]{new Object[]{new Object[]{new Object[]{"deep"}}}})))
            .add("empty chests", () -> eq(1, Practice.countItems(
                new Object[]{new Object[]{}, new Object[]{"a", new Object[]{}}, new Object[]{}})))
            .add("must be recursive", () -> mustCallItself("countItems")));

        return list;
    }

    static ArrayList<String> list(String... items) {
        return new ArrayList<>(Arrays.asList(items));
    }

    static HashMap<String, Integer> map(Object... pairs) {
        HashMap<String, Integer> m = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            m.put((String) pairs[i], (Integer) pairs[i + 1]);
        }
        return m;
    }

    // ---------- running everything ----------

    /** Runs one check on its own thread so an infinite loop can't freeze us. */
    static String runCheck(Check check) {
        final Throwable[] error = new Throwable[1];
        Thread t = new Thread(() -> {
            try {
                check.body.run();
            } catch (Throwable e) {
                error[0] = e;
            }
        });
        t.setDaemon(true);
        t.start();
        try {
            t.join(5000);
        } catch (InterruptedException e) {
            return "interrupted";
        }
        if (t.isAlive()) return "took too long (infinite loop?)";
        Throwable e = error[0];
        if (e == null) return null;
        if (e instanceof UnsupportedOperationException && "TODO".equals(e.getMessage())) {
            return "TODO";
        }
        if (e instanceof Fail) return e.getMessage();
        if (e instanceof StackOverflowError) {
            return "StackOverflowError (recursion never stops: missing base case?)";
        }
        return e.toString();
    }

    public static void main(String[] args) throws Exception {
        source = Files.readString(Path.of("Practice.java"));

        List<Problem> problems = buildProblems();
        int solved = 0;
        List<String> details = new ArrayList<>();

        System.out.println("=".repeat(56));
        System.out.println(" GAME DEV PRACTICE SET RESULTS");
        System.out.println("=".repeat(56));

        for (Problem p : problems) {
            int passed = 0;
            boolean notStarted = false;
            List<String> bad = new ArrayList<>();

            for (Check c : p.checks) {
                String result = runCheck(c);
                if (result == null) {
                    passed++;
                } else if (result.equals("TODO")) {
                    notStarted = true;
                    break;
                } else {
                    bad.add("  x " + c.name + ": " + result);
                }
            }

            if (notStarted) {
                System.out.println(" [ -- ] " + p.title + "  (not started)");
            } else if (bad.isEmpty()) {
                solved++;
                System.out.println(" [PASS] " + p.title + "  (" + passed + "/" + p.checks.size() + " tests)");
            } else {
                System.out.println(" [FAIL] " + p.title + "  (" + passed + "/" + p.checks.size() + " tests)");
                details.add("\n--- " + p.title + " ---");
                details.addAll(bad);
            }
        }

        System.out.println("-".repeat(56));
        System.out.println(" Solved " + solved + " of " + problems.size() + " problems");
        System.out.println("=".repeat(56));

        for (String line : details) System.out.println(line);

        if (solved == problems.size()) System.out.println("\nAll done. Great work!");
        System.exit(0);  // also stops any runaway threads
    }
}
